import{_ as o,o as r,c as e,a2 as s}from"./chunks/framework.G0y0PQA7.js";const g=JSON.parse('{"title":"SQL·DBML에서 시작하기","description":"","frontmatter":{},"headers":[],"relativePath":"quick/import-start.md","filePath":"quick/import-start.md"}'),a={name:"quick/import-start.md"};function i(d,t,l,n,c,p){return r(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="sql·dbml에서-시작하기" tabindex="-1">SQL·DBML에서 시작하기 <a class="header-anchor" href="#sql·dbml에서-시작하기" aria-label="Permalink to &quot;SQL·DBML에서 시작하기&quot;">​</a></h1><p>다른 도구나 DB 덤프에서 나온 SQL(<code>CREATE TABLE</code>)·DBML·Mermaid·Markdown 파일로 새 모델을 만듭니다. DB에 접속하지 않아도 됩니다.</p><ol><li><strong>가져오기 창 열기</strong> — 파일 › 가져오기 ▸ › SQL·DBML·Mermaid·Markdown에서…를 엽니다. 열린 문서가 없어도 됩니다. <code>.sql</code>·<code>.dbml</code>·<code>.mmd</code>·<code>.md</code> 파일을 창에 끌어다 놓아도 같은 창이 열립니다.</li><li><strong>입력 고르기</strong> — <strong>파일</strong>을 고르고 **찾아보기…**로 파일을 고르거나, <strong>붙여넣기</strong>를 골라 글을 그대로 붙여 넣습니다. 입력 형식과 SQL 방언은 자동으로 판별하므로 대개 그대로 두면 됩니다.</li><li><strong>가져올 곳</strong> — <strong>새 문서</strong>를 고릅니다. 열어 둔 모델에 더하려면 <strong>현재 문서에 합치기</strong>를 고릅니다.</li><li><strong>미리 보기</strong> — 찾은 테이블·컬럼·관계·인덱스 수와 경고를 확인합니다. 읽지 못한 문장은 건너뛰고 경고로 알려 줍니다.</li><li><strong>가져오기</strong> — 이름 없는 새 탭에 모델이 열립니다. 테이블 위치를 다듬은 뒤 <kbd>Ctrl</kbd>+<kbd>S</kbd>로 <code>.erm</code> 파일로 저장합니다.</li></ol><div class="tip custom-block"><p class="custom-block-title">팁</p><p>현재 문서에 합친 결과는 <kbd>Ctrl</kbd>+<kbd>Z</kbd> 한 번으로 모두 취소됩니다. 이름이 겹치는 객체는 덮어쓰기 · 건너뛰기 · 이름 바꿔 추가 중에서 고릅니다.</p></div><p>운영 중인 DB에 직접 접속해 구조를 가져오려면 <a href="/relio/quick/database">DB에서 가져오기·DB에 반영</a>을 보세요.</p><p><strong>자세히</strong> → <a href="/relio/features/import">가져오기와 다른 형식</a> · <a href="/relio/features/cli#relio-import">명령줄 › relio import</a></p>',6)])])}const _=o(a,[["render",i]]);export{g as __pageData,_ as default};
